insert into public.lessons (slug, title, summary, video_url, minutes, position) values
  ('parts-and-functions', 'Parts and functions of the sewing machine', 'Name each main part and know what it does.', 'https://drive.google.com/file/d/1zQI6PALl0xm0T06Nhv80rBpz0JMUI3Hh/preview', 5, 1),
  ('preparing-machine', 'Preparing the machine before use', 'Get the work area, needle and machine ready safely.', 'https://drive.google.com/file/d/1En30K60OExgoXnsE9oZJ1VDc7C4Vswaw/preview', 5, 2),
  ('threading-upper-thread', 'Threading the upper thread', 'Follow the thread path from spool to needle.', 'https://drive.google.com/file/d/1INL00uZxqj0OFnfM3MowJv4fPXiE18L7/preview', 5, 3),
  ('winding-bobbin', 'Winding the bobbin', 'Fill a bobbin evenly and remove it correctly.', 'https://drive.google.com/file/d/1R3X8_tZM8hdmKvGDb4_9jFvhImAUvNLV/preview', 5, 4),
  ('installing-bobbin', 'Installing the bobbin', 'Seat the bobbin and bring the bobbin thread up.', 'https://drive.google.com/file/d/1f5Ooy2-XflDmNnhVfsabrX-fWKd8XF_I/preview', 5, 5),
  ('stitch-length-operation', 'Stitch length and basic operation', 'Set the stitch length and control the machine while sewing.', 'https://drive.google.com/file/d/14DE7zgwUA6bD_j3w0Qmt9emSYlUl3lIl/preview', 5, 6),
  ('safety-practices', 'Sewing machine safety', 'Work safely around the needle and moving parts.', 'https://drive.google.com/file/d/1rj3KWVWG3U7sG8gkW8EVByD3r9bUT-sy/preview', 5, 7),
  ('cleaning-care', 'Cleaning and routine care', 'Keep the machine clean and ready for the next use.', 'https://drive.google.com/file/d/1ScsTgJYRfCXdrNw-a1K9PH-3H43CHDjz/preview', 5, 8)
insert into public.steps (id, lesson_slug, position, title, body) values
  ('parts-and-functions-1', 'parts-and-functions', 1, 'Feed dogs', 'The feed dogs are the teeth under the presser foot. They move the fabric forward while the needle goes up and down.'),
  ('parts-and-functions-2', 'parts-and-functions', 2, 'Tension regulator', 'The tension regulator sets how tight the upper thread is. Adjust it when the upper thread is too loose and the stitches are uneven.'),
  ('parts-and-functions-3', 'parts-and-functions', 3, 'Handwheel', 'Turn the handwheel toward you to raise or lower the needle by hand, for example to bring the needle to its highest point.'),
  ('parts-and-functions-4', 'parts-and-functions', 4, 'Presser foot and presser-foot lever', 'The presser foot holds the fabric firmly. The presser-foot lever raises and lowers the foot.'),
  ('parts-and-functions-5', 'parts-and-functions', 5, 'Spool pin and bobbin', 'The spool pin holds the spool that supplies the upper thread. The bobbin and bobbin case supply the lower thread.'),
  ('preparing-machine-1', 'preparing-machine', 1, 'Disconnect power first', 'If the machine is plugged in before you have checked the needle, bobbin and thread path, disconnect the power and finish the safety checks.'),
  ('preparing-machine-2', 'preparing-machine', 2, 'Check the needle', 'Replace a bent needle with a suitable, undamaged one.'),
  ('preparing-machine-3', 'preparing-machine', 3, 'Follow the preparation order', 'Prepare the work area, inspect the machine, check the needle and bobbin, prepare the needle and presser foot, connect the power, then test slowly.'),
  ('preparing-machine-4', 'preparing-machine', 4, 'Unplug before changing the needle', 'Turn off and unplug the machine before you change the needle.'),
  ('preparing-machine-5', 'preparing-machine', 5, 'Test slowly', 'Before placing fabric under the needle, test the machine slowly and carefully.'),
  ('threading-upper-thread-1', 'threading-upper-thread', 1, 'Seat the thread in the tension discs', 'Seat the thread properly between the tension discs. If this is missed, the upper thread becomes loose and the stitches are uneven.'),
  ('threading-upper-thread-2', 'threading-upper-thread', 2, 'Use the take-up lever', 'Passing the thread through the take-up lever controls the movement of the upper thread during sewing.'),
  ('threading-upper-thread-3', 'threading-upper-thread', 3, 'Raise the presser foot and needle first', 'Raise the presser foot and needle before threading. If you forget, the thread may not seat properly in the tension area.'),
  ('threading-upper-thread-4', 'threading-upper-thread', 4, 'Check the thread path', 'If the thread feels tangled or does not move smoothly after threading, check the threading path and rethread the machine.'),
  ('threading-upper-thread-5', 'threading-upper-thread', 5, 'Threading order', 'Raise the presser foot and needle, place the spool, follow the thread guides, tension area, take-up lever and remaining guides, then thread the needle.'),
  ('winding-bobbin-1', 'winding-bobbin', 1, 'Wind evenly', 'Check that the wound thread has no large gaps or loose loops. If it does, rewind the bobbin before installing it.'),
  ('winding-bobbin-2', 'winding-bobbin', 2, 'Do not overfill', 'An overfilled bobbin may not rotate smoothly.'),
  ('winding-bobbin-3', 'winding-bobbin', 3, 'Pass the thread through the bobbin', 'After placing the empty bobbin on the spindle, pass the thread through the bobbin as directed by the machine.'),
  ('winding-bobbin-4', 'winding-bobbin', 4, 'A well-wound bobbin', 'A bobbin that is ready to install is wound evenly, with no large gaps or loose loops.'),
  ('winding-bobbin-5', 'winding-bobbin', 5, 'Winding order', 'Place and secure the spool, follow the thread path, insert the empty bobbin, pass the thread, engage the winder, start slowly, stop when sufficiently filled, then cut and remove.'),
  ('installing-bobbin-1', 'installing-bobbin', 1, 'Turn the machine off', 'Turn off the machine before working around the needle and bobbin area.'),
  ('installing-bobbin-2', 'installing-bobbin', 2, 'Guide the thread', 'After placing the bobbin in its holder, pull the thread through the designated slot and under the tension spring or guide.'),
  ('installing-bobbin-3', 'installing-bobbin', 3, 'If the bobbin thread does not come up', 'Stop and check that the bobbin is seated correctly and the thread follows the proper path.'),
  ('installing-bobbin-4', 'installing-bobbin', 4, 'Bring up the bobbin thread', 'Hold the upper thread and turn the handwheel toward you to bring the bobbin thread up through the needle plate.'),
  ('installing-bobbin-5', 'installing-bobbin', 5, 'Installation order', 'Turn off the machine, raise the needle and presser foot, access the bobbin area, install the bobbin, guide the thread, close the cover, then bring the bobbin thread up.'),
  ('stitch-length-operation-1', 'stitch-length-operation', 1, 'Stitch-length control', 'If the stitches are too long, check the stitch-length control first.'),
  ('stitch-length-operation-2', 'stitch-length-operation', 2, 'Let the feed dogs move the fabric', 'The feed dogs are designed to move the fabric forward, so do not pull it.'),
  ('stitch-length-operation-3', 'stitch-length-operation', 3, 'Start slowly', 'Start slowly, then keep a steady speed.'),
  ('stitch-length-operation-4', 'stitch-length-operation', 4, 'When stitches look loose and uneven', 'Stop the machine and check the settings, the threading and the tension.'),
  ('stitch-length-operation-5', 'stitch-length-operation', 5, 'Basic sewing order', 'Select the stitch, place the practice fabric, lower the presser foot, hold the thread tails, start slowly, and guide the fabric gently.'),
  ('safety-practices-1', 'safety-practices', 1, 'Keep fingers clear of the needle', 'Guide the fabric from a safe position and keep your fingers away from the needle.'),
  ('safety-practices-2', 'safety-practices', 2, 'Unplug before changing the needle', 'Turn off and unplug the machine before you change a needle.'),
  ('safety-practices-3', 'safety-practices', 3, 'Keep loose items away', 'Keep loose clothing, jewelry, hair and other objects away from moving parts.'),
  ('safety-practices-4', 'safety-practices', 4, 'Switch off after sewing', 'When you finish sewing, switch off and unplug the machine.'),
  ('safety-practices-5', 'safety-practices', 5, 'Overall safe practice', 'Keep the area organized, inspect the machine, control your speed, keep fingers away from moving parts, and unplug before making adjustments.'),
  ('cleaning-care-1', 'cleaning-care', 1, 'Unplug before cleaning', 'Turn off and unplug the machine before you clean it.'),
  ('cleaning-care-2', 'cleaning-care', 2, 'Brush away lint', 'Use the appropriate cleaning brush to carefully remove lint and loose thread around the needle plate and bobbin area.'),
  ('cleaning-care-3', 'cleaning-care', 3, 'Replace a bent needle', 'Replace a bent needle with one suitable for the sewing activity.'),
  ('cleaning-care-4', 'cleaning-care', 4, 'Oiling and opening the machine', 'Do not oil the machine or disassemble internal parts unless the manufacturer''s instructions or your instructor require it.'),
  ('cleaning-care-5', 'cleaning-care', 5, 'Care after use', 'Unplug, clean lint and thread, check the needle and accessible components, return accessories, and cover the machine when appropriate.')
insert into public.quiz_questions (id, step_id, question, options, answer, explanation) values
  ('parts-and-functions-1-q', 'parts-and-functions-1', 'While sewing, a student notices that the fabric is not moving forward properly even though the needle is moving up and down. Which sewing machine part should the student check first?', '["Take-up lever","Feed dogs","Thread guide","Tension regulator"]'::jsonb, 1, ''),
  ('parts-and-functions-2-q', 'parts-and-functions-2', 'A student is preparing to sew but notices that the upper thread is too loose, resulting in uneven stitches. Which part should be adjusted to help correct the problem?', '["Tension regulator","Spool pin","Needle bar","Throat plate"]'::jsonb, 0, ''),
  ('parts-and-functions-3-q', 'parts-and-functions-3', 'Before removing the fabric, a student needs to position the needle at its highest point manually. Which part should be used, and in what direction should it be turned?', '["Take-up lever; away from the student","Handwheel; toward the student","Presser-foot lever; toward the student","Feed dogs; away from the student"]'::jsonb, 1, ''),
  ('parts-and-functions-4-q', 'parts-and-functions-4', 'Which situation best explains the relationship between the presser foot and presser-foot lever during sewing?', '["The lever controls the thread tension while the foot moves the fabric.","The foot carries the upper thread while the lever controls the needle.","The foot holds the fabric firmly, while the lever raises and lowers the foot.","The foot moves the fabric forward, while the lever controls the bobbin thread."]'::jsonb, 2, ''),
  ('parts-and-functions-5-q', 'parts-and-functions-5', 'A sewing machine produces a stitch using both an upper and a lower thread. Which pair of parts is directly responsible for providing and carrying these threads?', '["Spool pin and bobbin/bobbin case","Needle bar and throat plate","Feed dogs and presser foot","Take-up lever and handwheel"]'::jsonb, 0, ''),
  ('preparing-machine-1-q', 'preparing-machine-1', 'A student is ready to sew but notices that the sewing machine is plugged in before checking the needle, bobbin, and thread path. What should the student do first?', '["Start the machine slowly to test it.","Place fabric under the presser foot.","Disconnect the power and complete the necessary safety checks.","Press the foot control gently to see if the machine works."]'::jsonb, 2, ''),
  ('preparing-machine-2-q', 'preparing-machine-2', 'While preparing the machine, a student discovers that the needle is slightly bent. What is the most appropriate action?', '["Continue using it at a slower speed.","Adjust the presser foot to compensate for the bent needle.","Replace it with a suitable, undamaged needle.","Tighten the needle bar to keep it in place."]'::jsonb, 2, ''),
  ('preparing-machine-3-q', 'preparing-machine-3', 'Which sequence demonstrates the safest preparation of the sewing machine before actual sewing?', '["Plug in → test machine → check needle → install bobbin","Prepare work area → inspect machine → check needle and bobbin → prepare needle and presser foot → connect power → test slowly","Install bobbin → plug in → prepare work area → test machine → check needle","Test machine → connect power → inspect cord → prepare work area → begin sewing"]'::jsonb, 1, ''),
  ('preparing-machine-4-q', 'preparing-machine-4', 'A student needs to change the needle because it is damaged. The machine is still connected to the power supply. What should the student do before changing the needle?', '["Raise the presser foot and continue working.","Turn off and unplug the machine.","Press the foot control to lower the needle.","Remove the bobbin while the machine is running."]'::jsonb, 1, ''),
  ('preparing-machine-5-q', 'preparing-machine-5', 'After completing the preparation steps, a student wants to make sure the machine is functioning properly before placing fabric under the needle. What should the student do?', '["Immediately sew at high speed.","Test the machine slowly and carefully.","Increase the thread tension first.","Hold the needle with the fingers while testing."]'::jsonb, 1, ''),
  ('threading-upper-thread-1-q', 'threading-upper-thread-1', 'A student has placed the thread on the spool pin but notices that the upper thread becomes loose and produces uneven stitches. Which step may have been missed or done incorrectly?', '["Pulling several centimeters of thread through the needle eye","Seating the thread properly between the tension discs","Placing the thread behind the presser foot","Raising the presser foot after threading"]'::jsonb, 1, ''),
  ('threading-upper-thread-2-q', 'threading-upper-thread-2', 'Why is it important to pass the upper thread through the take-up lever during threading?', '["It holds the spool securely on the spool pin.","It guides the lower thread into the bobbin.","It controls the movement of the upper thread during sewing.","It prevents the needle from moving while sewing."]'::jsonb, 2, ''),
  ('threading-upper-thread-3-q', 'threading-upper-thread-3', 'A student follows the threading path but forgets to raise the presser foot and needle before starting. What is the most likely problem?', '["The bobbin will automatically become empty.","The thread may not be properly seated in the tension area.","The feed dogs will stop moving permanently.","The needle will automatically become damaged."]'::jsonb, 1, ''),
  ('threading-upper-thread-4-q', 'threading-upper-thread-4', 'After threading the machine, the student gently pulls the thread and feels that it is tangled and does not move smoothly. What should the student do?', '["Start sewing slowly to untangle the thread.","Increase the sewing speed.","Leave the thread as it is and continue sewing.","Check the threading path and rethread the machine correctly."]'::jsonb, 3, ''),
  ('threading-upper-thread-5-q', 'threading-upper-thread-5', 'Which sequence correctly represents the general order of threading the upper thread?', '["Thread needle → place spool → tension area → take-up lever → thread guides","Raise presser foot and needle → place spool → thread guides → tension area → take-up lever → remaining guides → needle","Place spool → thread needle → raise needle → take-up lever → tension area","Raise needle → thread needle → place spool → tension area → thread guides → take-up lever"]'::jsonb, 1, ''),
  ('winding-bobbin-1-q', 'winding-bobbin-1', 'A student winds a bobbin and notices that the thread has large gaps and loose loops. What should the student do before installing the bobbin?', '["Install it immediately and sew slowly.","Add more thread until the bobbin is completely full.","Check and rewind the bobbin so the thread is evenly wound.","Remove the thread from the spool pin and start sewing."]'::jsonb, 2, ''),
  ('winding-bobbin-2-q', 'winding-bobbin-2', 'Why should a bobbin not be overfilled during the winding process?', '["It can prevent the bobbin from rotating smoothly.","It can make the needle move faster.","It can automatically loosen the presser foot.","It can cause the spool pin to stop rotating."]'::jsonb, 0, ''),
  ('winding-bobbin-3-q', 'winding-bobbin-3', 'A student has inserted an empty bobbin onto the spindle but has not yet passed the thread through the bobbin. What should the student do next?', '["Remove the bobbin and install it in the bobbin case.","Pass the thread through the bobbin as directed by the machine.","Begin sewing without winding the bobbin.","Cut the thread and remove the bobbin."]'::jsonb, 1, ''),
  ('winding-bobbin-4-q', 'winding-bobbin-4', 'Which situation shows that the bobbin is properly prepared for installation?', '["The thread is tightly packed with excessive winding.","The thread has large gaps but does not fall off the bobbin.","The thread is wound evenly without large gaps or loose loops.","The thread is loosely wound so it can rotate faster."]'::jsonb, 2, ''),
  ('winding-bobbin-5-q', 'winding-bobbin-5', 'Which sequence best represents the correct procedure for winding a bobbin?', '["Insert bobbin → place spool → start machine → guide thread → remove bobbin","Place and secure spool → follow thread path → insert empty bobbin → pass thread → engage winder → start slowly → stop when sufficiently filled → cut and remove","Start machine → insert bobbin → engage winder → place spool → cut thread","Place spool → remove empty bobbin → install bobbin case → start sewing → cut thread"]'::jsonb, 1, ''),
  ('installing-bobbin-1-q', 'installing-bobbin-1', 'A student is about to install a bobbin and notices that the sewing machine is still turned on. What should the student do first?', '["Raise the needle and continue installing the bobbin.","Turn off the machine before working around the needle and bobbin area.","Press the foot control to raise the needle.","Remove the bobbin cover while the machine is running."]'::jsonb, 1, ''),
  ('installing-bobbin-2-q', 'installing-bobbin-2', 'After placing the wound bobbin into the bobbin holder, which action is most important for ensuring proper thread movement?', '["Pull the thread through the designated slot and under the tension spring or guide.","Pull the thread directly toward the front of the machine.","Cut the bobbin thread as close to the bobbin as possible.","Hold the bobbin tightly while turning the handwheel."]'::jsonb, 0, ''),
  ('installing-bobbin-3-q', 'installing-bobbin-3', 'A student has installed the bobbin and closed the bobbin cover, but the bobbin thread does not come up when the handwheel is turned. What should the student do?', '["Start sewing at a higher speed.","Pull the upper thread harder.","Stop and check whether the bobbin is seated correctly and the thread follows the proper path.","Remove the presser foot and continue sewing."]'::jsonb, 2, ''),
  ('installing-bobbin-4-q', 'installing-bobbin-4', 'After installing the bobbin, what is the correct way to bring the bobbin thread up through the needle plate?', '["Turn the handwheel away from you while holding the bobbin thread.","Hold the upper thread and turn the handwheel toward you.","Pull the bobbin thread upward without using the handwheel.","Press the foot control while holding both threads."]'::jsonb, 1, ''),
  ('installing-bobbin-5-q', 'installing-bobbin-5', 'Which sequence correctly describes the procedure for installing the bobbin?', '["Install bobbin → turn on machine → close cover → raise needle → pull threads","Turn off machine → raise needle and presser foot → access bobbin area → install bobbin correctly → guide thread through slot/tension guide → close cover → bring bobbin thread up","Raise presser foot → start machine → install bobbin → pull thread → close cover","Open bobbin area → install bobbin → turn on machine → raise needle → check thread path"]'::jsonb, 1, ''),
  ('stitch-length-operation-1-q', 'stitch-length-operation-1', 'A student notices that the stitches on the practice fabric are too long. Which machine setting should the student check first?', '["Stitch-length control","Presser-foot lever","Handwheel","Bobbin cover"]'::jsonb, 0, ''),
  ('stitch-length-operation-2-q', 'stitch-length-operation-2', 'While sewing, a student pulls the fabric strongly toward the back because it is not moving fast enough. Why is this incorrect?', '["The needle will automatically become shorter.","The feed dogs are designed to move the fabric forward.","The stitch pattern will automatically change.","The presser foot will become loose."]'::jsonb, 1, ''),
  ('stitch-length-operation-3-q', 'stitch-length-operation-3', 'A beginner is practicing on a sewing machine for the first time. Which approach demonstrates proper machine control?', '["Start at high speed to finish quickly.","Push the fabric forcefully while sewing.","Start slowly and gradually maintain a steady speed.","Keep the presser foot raised while sewing."]'::jsonb, 2, ''),
  ('stitch-length-operation-4-q', 'stitch-length-operation-4', 'A student has selected the correct stitch setting but notices that the stitches are loose and uneven. According to the video, what should the student do?', '["Continue sewing until the stitches become even.","Increase the machine speed immediately.","Stop the machine and check the settings, threading, and tension.","Pull the fabric harder to improve the stitches."]'::jsonb, 2, ''),
  ('stitch-length-operation-5-q', 'stitch-length-operation-5', 'Which sequence best demonstrates the proper procedure before and during basic sewing practice?', '["Start the machine → lower presser foot → place fabric → select stitch → guide fabric","Select stitch setting → place practice fabric → lower presser foot → hold thread tails → start slowly → guide fabric gently","Place fabric → pull fabric forward → start at high speed → adjust stitch length","Lower presser foot → start machine → select stitch pattern → pull fabric forcefully"]'::jsonb, 1, ''),
  ('safety-practices-1-q', 'safety-practices-1', 'While the sewing machine is running, a student notices that the fabric is close to the needle and places their fingers directly in front of it to guide the fabric. What should the student do instead?', '["Press the foot control harder to move the fabric faster.","Guide the fabric from a safe position while keeping the fingers away from the needle.","Hold the fabric tightly with both hands in front of the needle.","Continue sewing because the fabric needs to be controlled closely."]'::jsonb, 1, ''),
  ('safety-practices-2-q', 'safety-practices-2', 'A student needs to change the needle because it is damaged. The machine is still plugged in. Which action should be performed before changing the needle?', '["Lower the presser foot and continue working.","Reduce the sewing speed.","Turn off and unplug the machine.","Hold the needle carefully while removing it."]'::jsonb, 2, ''),
  ('safety-practices-3-q', 'safety-practices-3', 'During sewing, a student''s loose bracelet becomes close to the moving parts of the machine. What safety rule applies to this situation?', '["Always increase the sewing speed when using small fabric.","Keep loose clothing, jewelry, hair, and other objects away from moving parts.","Hold the jewelry with one hand while sewing with the other.","Continue sewing as long as the machine is functioning properly."]'::jsonb, 1, ''),
  ('safety-practices-4-q', 'safety-practices-4', 'A student finishes sewing and immediately leaves the classroom without turning off the machine. Which part of the safety procedure was neglected?', '["Inspecting the needle before use","Maintaining a comfortable sitting position","Switching off and unplugging the machine after sewing","Selecting the appropriate stitch pattern"]'::jsonb, 2, ''),
  ('safety-practices-5-q', 'safety-practices-5', 'Which situation demonstrates the best overall safety practice when operating a sewing machine?', '["Working quickly while keeping the machine running between tasks","Keeping the area organized, inspecting the machine, controlling speed, keeping fingers away from moving parts, and unplugging before adjustments","Focusing mainly on sewing speed while checking the machine only after finishing","Leaving the machine running while briefly getting materials from another area"]'::jsonb, 1, ''),
  ('cleaning-care-1-q', 'cleaning-care-1', 'A student is about to clean the sewing machine and notices that it is still connected to the power supply. What should the student do first?', '["Begin cleaning the bobbin area carefully.","Turn off and unplug the sewing machine.","Remove the needle while the machine is connected.","Wipe the machine while it is running."]'::jsonb, 1, ''),
  ('cleaning-care-2-q', 'cleaning-care-2', 'After several sewing activities, a student notices a large amount of lint and loose thread around the needle plate and bobbin area. What is the most appropriate action?', '["Use the appropriate cleaning brush to carefully remove the lint and loose thread.","Use the machine at high speed to remove the lint.","Apply oil immediately to the entire machine.","Disassemble the internal parts without checking the instructions."]'::jsonb, 0, ''),
  ('cleaning-care-3-q', 'cleaning-care-3', 'A student notices that the sewing machine''s needle is bent after an activity. What should the student do before storing the machine?', '["Continue using the needle until it breaks.","Straighten the needle and reuse it.","Replace the needle with one suitable for the sewing activity.","Apply oil to the needle."]'::jsonb, 2, ''),
  ('cleaning-care-4-q', 'cleaning-care-4', 'A student wants to maintain the sewing machine and plans to apply oil and open its internal parts without consulting the manual. According to the video, what should the student do?', '["Proceed because regular oiling is always required.","Disassemble the machine to remove hidden dust.","Apply oil only after cleaning the external surfaces.","Avoid oiling or internal disassembly unless required by the manufacturer''s instructions or instructor."]'::jsonb, 3, ''),
  ('cleaning-care-5-q', 'cleaning-care-5', 'Which sequence best represents proper routine care after using a sewing machine?', '["Cover the machine → clean lint → unplug → check needle → store accessories","Unplug → clean lint and thread → check the needle and accessible components → return accessories → cover the machine when appropriate","Apply oil → disassemble internal parts → clean → plug in → cover the machine","Remove all internal parts → wipe the machine → plug it in → store accessories"]'::jsonb, 1, '')
insert into public.checklists (slug, title, items, position) values
  ('before-sewing', 'Before you sew', '["Machine sits on a steady table","Needle is sharp and inserted correctly","Bobbin is wound evenly","Top thread and bobbin thread are in place","Scrap fabric is ready for a test seam","Presser foot is down before stitching"]'::jsonb, 1),
  ('tension-check', 'Tension check', '["Two contrasting threads loaded","Test seam sewn","Both sides of the seam checked","Dial changed by one number","Test seam sewn again"]'::jsonb, 2),
  ('after-sewing', 'After you sew', '["Machine is switched off and unplugged","Needle and presser foot are raised","Fabric removed and threads trimmed","Lint brushed from the bobbin area","Machine covered"]'::jsonb, 3)
insert into public.parts (slug, name, fn, x, y, position) values
  ('spool-pin', 'Spool pin', 'Holds the spool of thread on top of the machine.', 200, 34, 1),
  ('bobbin-winder', 'Bobbin winder', 'Fills the bobbin with thread from the spool.', 245, 34, 2),
  ('take-up-lever', 'Take-up lever', 'Moves up and down to pull thread from the spool and tighten each stitch. The thread passes through its eye.', 75, 50, 3),
  ('tension-dial', 'Tension regulator', 'Sets how tightly the upper thread is held. A higher number pulls the upper thread tighter.', 125, 62, 4),
  ('stitch-selector', 'Stitch selector and stitch-length control', 'Chooses the stitch pattern and the stitch length.', 170, 62, 5),
  ('needle', 'Needle', 'Carries the top thread through the fabric to meet the bobbin thread.', 62, 118, 6),
  ('presser-foot', 'Presser foot', 'Holds the fabric flat against the feed dogs while you sew. Lift it to thread the machine.', 63, 142, 7),
  ('feed-dogs', 'Feed dogs and throat plate', 'The metal teeth under the presser foot move the fabric forward. The throat plate is the flat plate around them.', 100, 160, 8),
  ('handwheel', 'Handwheel', 'Turn it toward you to raise or lower the needle by hand.', 296, 62, 9),
  ('foot-pedal', 'Foot pedal', 'Controls sewing speed. Press gently to start slowly.', 270, 211, 10),
  ('thread-guide', 'Thread guide', 'Guides the thread along its path from the spool to the needle.', 150, 30, 11),
  ('needle-bar', 'Needle bar', 'Holds the needle and moves it up and down.', 62, 96, 12),
  ('presser-foot-lever', 'Presser-foot lever', 'Raises and lowers the presser foot.', 36, 96, 13),
  ('bobbin-case', 'Bobbin and bobbin case', 'The bobbin holds the lower thread and sits in the bobbin case under the needle plate.', 150, 175, 14)
insert into public.faqs (q, a, position) values
  ('Do I need to log in?', 'No. Browse every lesson without an account. Log in only if you want your progress saved across devices.', 1),
  ('How is my progress saved?', 'Automatically on this device. After you log in, it syncs to your account so you can continue on another phone or computer.', 2),
  ('Why does my top thread keep breaking?', 'Rethread with the presser foot up, check that the needle is straight, and lower the top tension by one number.', 3),
  ('Why is thread bunching under my fabric?', 'The top thread is usually not seated in the tension discs. Raise the presser foot and thread the machine again.', 4)
insert into public.achievements (slug, title, description, criteria, position) values
  ('first-step', 'First step', 'Pass your first quiz.', 'steps:1', 1),
  ('parts-spotter', 'Parts spotter', 'Finish the parts and functions lesson.', 'lesson:parts-and-functions', 2),
  ('ready-to-sew', 'Ready to sew', 'Finish the machine preparation lesson.', 'lesson:preparing-machine', 3),
  ('thread-pro', 'Thread pro', 'Finish the upper threading lesson.', 'lesson:threading-upper-thread', 4),
